  SIGNAL out_rsvd_1                       : signed(7 DOWNTO 0) := to_signed(16#00#, 8);  -- int8
  SIGNAL alpha1_D_Lookup_Table_out1       : signed(7 DOWNTO 0);  -- int8

BEGIN
  init_guard_true_1 <= '1';

  matching_delays_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        init_guard_true_2 <= '0';
      ELSIF enb = '1' THEN
        init_guard_true_2 <= init_guard_true_1;
      END IF;
    END IF;
  END PROCESS matching_delays_process;


  outinit_guard_default <= to_signed(16#00#, 8);

  -- Count limited, Unsigned Counter
  --  initial value   = 0
  --  step value      = 1
  --  count to value  = 2979
  count_step <= to_unsigned(16#001#, 12);

  count_from <= to_unsigned(16#000#, 12);

  count_reset <= to_unsigned(16#000#, 12);

  count <= HDL_Counter_out1 + count_step;

  
  need_to_wrap <= '1' WHEN HDL_Counter_out1 = to_unsigned(16#BA3#, 12) ELSE
      '0';

  
  count_value <= count WHEN need_to_wrap = '0' ELSE
      count_from;

  
  count_1 <= HDL_Counter_out1 WHEN nxtBit = '0' ELSE
      count_value;

  
  count_2 <= count_1 WHEN rst = '0' ELSE
      count_reset;

  HDL_Counter_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        HDL_Counter_out1 <= to_unsigned(16#000#, 12);
      ELSIF enb = '1' THEN
        HDL_Counter_out1 <= count_2;
      END IF;
    END IF;
  END PROCESS HDL_Counter_process;


  
  prelookup_idx <= to_unsigned(16#000#, 12) WHEN HDL_Counter_out1 = to_unsigned(16#000#, 12) ELSE
      to_unsigned(16#BA3#, 12) WHEN HDL_Counter_out1 >= to_unsigned(16#BA3#, 12) ELSE
      HDL_Counter_out1;

  out_rsvd <= alpha1_D_Lookup_Table_table_data(to_integer(prelookup_idx));

  PipelineRegister_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF enb = '1' THEN
        out_rsvd_1 <= out_rsvd;
      END IF;
    END IF;
  END PROCESS PipelineRegister_process;


  
  alpha1_D_Lookup_Table_out1 <= outinit_guard_default WHEN init_guard_true_2 = '0' ELSE
      out_rsvd_1;

  dataIn <= std_logic_vector(alpha1_D_Lookup_Table_out1);

END rtl;

